pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        // burn first to get initial state (mint to owner so burn is possible)
        // Use bound to ensure the burn amount is within the owner's balance
        uint256 ownerBalance = c.balanceOf(address(this));
        vm.assume(burnAmount <= ownerBalance);

        uint256 totalSupplyBefore = c.totalSupply();
        c.burn(burnAmount);
        uint256 totalSupplyAfter = c.totalSupply();

        // General rule: totalSupply should decrease by exactly burnAmount
        assertTrue(totalSupplyAfter == totalSupplyBefore - burnAmount);
    }
}

