// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, uint256 burnAmount) public {
        // Restrict inputs to satisfy reference requirements
        vm.assume(initialSupply <= type(uint256).max / 2); // avoid overflow in setup
        vm.assume(burnAmount <= initialSupply * 1e10); // balance sufficient
        // Deploy with fresh state
        c = new C(initialSupply, "Token", "TKN");
        // Record pre-burn values
        uint256 preTotalSupply = c.totalSupply();
        uint256 preOwnerBalance = c.balanceOf(address(this));
        // Perform burn
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.burn.selector, burnAmount));
        if (success) {
            uint256 postTotalSupply = c.totalSupply();
            uint256 postOwnerBalance = c.balanceOf(address(this));
            // The sum totalSupply + ownerBalance should not increase
            assertTrue(preTotalSupply + preOwnerBalance >= postTotalSupply + postOwnerBalance);
        }
    }
}

