pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 initialSupply, string memory tokenName, string memory tokenSymbol) public {
        // Restrict input to avoid overflow in constructor
        vm.assume(initialSupply <= 1e25);
        // Deploy with fuzzed params
        c = new C(initialSupply, tokenName, tokenSymbol);
        uint256 supplyBeforeBurn = c.totalSupply();
        // Call burn with a value that is guaranteed to be available
        uint256 burnAmount = bound(burnAmount, 0, supplyBeforeBurn);
        // Ensure the owner has enough balance (the owner is msg.sender for this test)
        vm.assume(c.balanceOf(address(this)) >= burnAmount);
        c.burn(burnAmount);
        uint256 supplyAfterBurn = c.totalSupply();
        // General rule: totalSupply should decrease or stay the same after burn
        assertTrue(supplyAfterBurn <= supplyBeforeBurn);
    }
}

