pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 value) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("mintToken(address,uint256)", caller, 1000));
        require(success);

        uint256 balanceBefore = c.balanceOf(caller);
        uint256 supplyBefore = c.totalSupply();

        value = bound(value, 0, balanceBefore);

        (bool reverted, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", value));

        uint256 balanceAfter = c.balanceOf(caller);
        uint256 supplyAfter = c.totalSupply();

        assertTrue(supplyAfter == supplyBefore - (reverted ? 0 : value) && balanceAfter == balanceBefore - (reverted ? 0 : value) && supplyAfter >= 0);
    }
}

