        c.transfer(address(this), 1);
        vm.prank(burner);
        bool burnt = c.burn(amount);
        uint256 balAfter = c.balanceOf(burner);
        assertTrue(balAfter <= balBefore + (burnt ? 0 : amount));
    }
}

