pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(uint256 burnAmount) public {
        uint256 initialSupply = c.totalSupply();
        vm.assume(burnAmount > 0 && burnAmount <= initialSupply);
        address caller = address(this);
        (bool success, ) = address(c).call(abi.encodeWithSignature("burn(uint256)", burnAmount));
        require(success);
        uint256 totalAfter = c.totalSupply();
        uint256 callerBalance = c.balanceOf(caller);
        uint256 totalBalances = 0;
        totalBalances += callerBalance;
        for (address a; a != address(0); a = address(uint160(a) + 1)) {
