        vm.assume(burnAmount <= type(uint256).max / 2);
        vm.assume(mintAmount <= type(uint256).max / 2);

        // Record initial totalSupply (should be 0 after deployment)
        uint256 initialSupply = c.totalSupply();

        // Mint tokens to target (onlyOwner is the deployer, which is this contract)
        c.mintToken(target, mintAmount);

        // Record supply after mint
        uint256 postMintSupply = c.totalSupply();

        // Burn tokens from the contract's balance (which holds the minted tokens)
        // First ensure the contract has enough balance (it does because all minted are here)
        c.burn(burnAmount);

        // After burn, totalSupply must be >= postMintSupply - burnAmount (since burn decreases it linearly)
        // In the reference: totalSupply after burn = postMintSupply - burnAmount
        // In the buggy version: totalSupply after burn = postMintSupply - burnAmount + mintAmount (because mint subtracted!)
        // So the property: totalSupply <= postMintSupply - burnAmount + (some small epsilon?) Actually let's derive.
        // For reference: totalSupply_final = initialSupply + mintAmount - burnAmount
        // For buggy: totalSupply_final = initialSupply - mintAmount - burnAmount (since mint decreased by mintAmount, burn decreases by burnAmount)
        // Therefore: reference final >= buggy final (since mintAmount >= 0). So we assert:
        // totalSupply >= postMintSupply - burnAmount - mintAmount??? Not exactly.
        // Simpler: The reference always satisfies that totalSupply never decreases by more than burnAmount after a mint+ burn sequence?
        // Actually, the difference: after mint and burn, totalSupply in reference is initialSupply + mintAmount - burnAmount.
        // After the same in buggy, totalSupply is initialSupply - mintAmount - burnAmount.
        // So reference >= buggy + 2*mintAmount > buggy. Thus a property: totalSupply >= initialSupply - burnAmount (since buggy totalSupply can be negative? No, but underflow).
        // Strictly: buggy totalSupply = initialSupply - mintAmount - burnAmount. Reference totalSupply = initialSupply + mintAmount - burnAmount.
        // So reference totalSupply >= initialSupply + 0 - burnAmount = initialSupply - burnAmount.
        // Buggy totalSupply = initialSupply - mintAmount - burnAmount <= initialSupply - burnAmount (since mintAmount >= 0).
        // So property: totalSupply >= initialSupply - burnAmount holds for reference, fails for buggy when mintAmount > 0.
        // Let's write that:
        uint256 finalSupply = c.totalSupply();
        assertTrue(finalSupply >= initialSupply - burnAmount);
    }
}

