import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address target, bool freezeBefore, uint256 burnAmount) public {
        // Ensure burnAmount is valid (owner's balance starts at 0, so we mint first)
        // Use vm.assume to avoid unrealistic large numbers
        vm.assume(burnAmount < 1e30);
        // Mint tokens to owner and target to work with
        // We need to set up: freeze target, then burn, then check target's frozen state
        // First, mint tokens to msg.sender (owner) so burn can succeed
        address owner = address(this); // test contract is owner (since no owner set yet)
        c.mintToken(owner, burnAmount + 1); // ensure enough supply
        // Freeze target to some state
        c.freezeAccount(target, freezeBefore);
        // Record frozen state after freeze
        bool frozenBeforeBurn = c.frozenAccount(target);
        // Now perform burn (onlyOwner, so must be called from test contract)
        // Use try/catch to handle revert cases
        bool burnSuccess;
        try c.burn(burnAmount) {
            burnSuccess = true;
        } catch {
            burnSuccess = false;
        }
        // If burn succeeded (which should always be the case with minted balance), 
        // then frozen state of any address should remain unchanged
        // The bug: freezeAccount toggles msg.sender instead of target; but test contract is owner, 
        // so if target != owner, frozenState of target should not change.
        // For the reference C: frozenAccount(target) remains freezeBefore.
        // For mutant M: frozenAccount(target) also unchanged (since it changes msg.sender, target unaffected).
        // Wait — mutant changes frozenAccount[msg.sender], not frozenAccount[target]. 
        // So if target == msg.sender (test contract), then M would change that, but if they differ, M leaves target unchanged.
        // To make test fail on mutant, we need a case where target != msg.sender; then reference freezes target, mutant does not.
        // So we enforce target != msg.sender (owner) via vm.assume
        vm.assume(target != owner);
        // Now: after burn, frozenAccount(target) should equal freezeBefore for reference C (since freeze was already applied).
        // Actually, reference C: freezeAccount sets frozenAccount[target] = freeze, so after freeze, it's set.
        // Then burn does not affect frozenAccount. So after burn, it should still be freezeBefore.
        // Mutant M: freezeAccount sets frozenAccount[msg.sender] = freeze, so frozenAccount[target] remains unchanged (default false).
        // So after burn (which does nothing to frozenAccount), frozenAccount[target] should be false if it was never changed before.
        // But we called freezeAccount with freezeBefore, so if freezeBefore == false, then reference has false, mutant also false (coincidence).
        // If freezeBefore == true, reference has true, mutant has false. So we need freezeBefore == true to expose difference.
        vm.assume(freezeBefore == true);
        // Now check: after burn (whether it reverted or not, because burn may fail if balance insufficient? We have minted enough, so succeeds.)
        // The rule: frozenAccount(target) should remain unchanged from freezeBefore after burn.
        bool frozenAfterBurn = c.frozenAccount(target);
        assertTrue(frozenAfterBurn == freezeBefore, "Freeze state of target should not change by burn");
    }
}

