pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address to, uint256 value) public {
        vm.assume(to != address(0) && to != address(this));
        vm.assume(value > 0 && value <= type(uint256).max / 2);

        // Mint tokens to this contract (sender) so we can transfer
        c.mintToken(address(this), value);

        // First transfer
        bool ret1 = c.transfer(to, value);

        // Mint again to this contract for second transfer
        c.mintToken(address(this), value);

        // Second transfer
        bool ret2 = c.transfer(to, value);

        // In the reference, both transfers return true. In the buggy version, both return false.
        // So the product of their complement-to-true is always 1 (true) for reference.
        // For buggy version, both are false, so (true - ret1) * (true - ret2) = 1 still holds.
        // But the rule must be broken: we assert that ret1 != ret2 is false for reference (both true) and true for buggy (both false) — no difference.
        // Instead, we assert that the return value is the same for both calls.
        assertTrue(ret1 == ret2);
    }
}

