pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, 0, 0); }
    function testFuzz_property(address caller, uint256 burnAmount) public {
        vm.assume(caller != address(0));
        vm.assume(burnAmount > 0 && burnAmount <= type(uint256).max / 1e18);
        address owner = c.owner();
        vm.prank(owner);
        c.mintToken(caller, burnAmount);
        uint256 preBalance = c.balanceOf(caller);
        uint256 preTotalSupply = c.totalSupply();
        vm.prank(caller);
        bool success;
        if (preBalance >= burnAmount) {
            c.burn(burnAmount);
            success = true;
        } else {
            vm.expectRevert();
            c.burn(burnAmount);
            success = false;
        }
        if (success) {
            assertTrue(c.balanceOf(caller) == preBalance - burnAmount && c.totalSupply() == preTotalSupply - burnAmount);
        }
    }
}

